function isGetal(waarde) {
    return typeof waarde === "number" && Number.isFinite(waarde);
}

const data = msg.payload;
const topic = msg.topic;

if (!data || typeof data !== "object" || !data.station || !data.ts) {
    node.warn("Meting heeft ontbrekende velden: " + topic);
    return null;
}

let geldig = false;

switch (topic) {
    case "weer/temperatuur":
        geldig = isGetal(data.waarde) && data.waarde >= -50 && data.waarde <= 60;
        break;
    case "weer/luchtvochtigheid":
        geldig = isGetal(data.waarde) && data.waarde >= 0 && data.waarde <= 100;
        break;
    case "weer/wind":
        geldig = isGetal(data.snelheid) && data.snelheid >= 0 && data.snelheid <= 200 &&
            isGetal(data.richting) && data.richting >= 0 && data.richting <= 360;
        break;
    case "weer/regen":
        geldig = isGetal(data.mm_per_uur) && data.mm_per_uur >= 0 && data.mm_per_uur <= 500;
        break;
    default:
        return null;
}

if (!geldig) {
    node.warn("Ongeldige meting afgewezen: " + topic);
    return null;
}

msg.topic = topic;
return msg;
